CREATE OR REPLACE PROCEDURE log_login_attempt (...)
IS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO login_audit (username, attempted_at)
  VALUES (p_username, SYSTIMESTAMP);
  COMMIT;  -- commits ONLY this, independent of the caller
END;
/

log_login_attempt('system', TRUE);  -- commits immediately
UPDATE accounts SET balance = balance - p_amount ...;
IF p_amount > 1000000 THEN
  RAISE_APPLICATION_ERROR(-20001, 'Over limit');
  -- rolls back the updates, NOT the audit row
END IF;

PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO login_audit (username) VALUES ('test');
  -- Missing COMMIT/ROLLBACK here raises
  -- ORA-06519: active autonomous transaction detected
END;
